package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.math.*; import java.util.*;
public class RegisterPaymentService implements RegisterPaymentUseCase { private final OrderRepositoryPort orders; private final PaymentRepositoryPort payments; private final OperationAuditPort audit; public RegisterPaymentService(OrderRepositoryPort o,PaymentRepositoryPort p,OperationAuditPort a){orders=o;payments=p;audit=a;}
 public Payment registerPayment(User actor,String oid,String paymentId,BigDecimal amount,boolean approved){Order o=ServiceSupport.required(orders.findById(oid),"Order",oid);ServiceSupport.sameCustomer(actor,o.getCustomer());if(o.getStatus()!=DomainTypes.OrderStatus.PENDING_PAYMENT)throw new DomainRuleException("Order is not awaiting payment");if(amount.compareTo(o.getTotal())<0)throw new DomainRuleException("Payment is insufficient");Payment p=new Payment(paymentId,o,amount);if(approved)p.approve();else p.decline();Payment saved=payments.save(p);orders.update(o);audit.record(actor,"REGISTER_PAYMENT",paymentId,Map.of("orderId",oid,"approved",approved));return saved;}
}
